import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int a = Integer.parseInt(inputLine[0]);
        int b = Integer.parseInt(inputLine[1]);

        List<Integer> primes = generatePrimes(6000);
        Map<Integer, Integer> fDict = new HashMap<>();
        fDict.put(0, 0);
        fDict.put(1, 1);
        fDict.put(2, 2);

        for (int i = 3; i <= a; i++) {
            int val = 2 * fDict.get(i - 1);
            for (int divisor : generateFactors(i, primes)) {
                if (divisor >= 2 && divisor <= i) {
                    int quotient = i / divisor;
                    int prevDivisor = (i - 1) / divisor;
                    val += fDict.get(quotient) - fDict.get(prevDivisor);
                    val %= b;
                }
            }
            val %= b;
            fDict.put(i, val);
        }
        System.out.println(fDict.get(a));
    }

    private static List<Integer> generatePrimes(int limit) {
        List<Integer> primes = new ArrayList<>();
        for (int candidate = 2; candidate < limit; candidate++) {
            boolean isPrime = true;
            for (int prime : primes) {
                if (prime * prime > candidate) {
                    break;
                }
                if (candidate % prime == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(candidate);
            }
        }
        return primes;
    }

    private static List<Integer> generateFactors(int number, List<Integer> primes) {
        Map<Integer, Integer> primeFactors = factorize(number, primes);
        List<Integer> resultList = new ArrayList<>();
        resultList.add(1);
        for (Map.Entry<Integer, Integer> entry : primeFactors.entrySet()) {
            int prime = entry.getKey();
            int count = entry.getValue();
            List<Integer> tempList = new ArrayList<>();
            for (int val : resultList) {
                for (int power = 0; power <= count; power++) {
                    tempList.add(val * (int) Math.pow(prime, power));
                }
            }
            resultList = tempList;
        }
        return resultList;
    }

    private static Map<Integer, Integer> factorize(int number, List<Integer> primes) {
        Map<Integer, Integer> factorsMap = new HashMap<>();
        int tempNumber = number;
        for (int prime : primes) {
            if (prime * prime > tempNumber) {
                break;
            }
            int count = 0;
            while (tempNumber % prime == 0) {
                tempNumber /= prime;
                count++;
            }
            if (count > 0) {
                factorsMap.put(prime, count);
            }
        }
        if (tempNumber > 1) {
            factorsMap.put(tempNumber, 1);
        }
        return factorsMap;
    }
}
